//go:build go1.26 && goexperiment.simd && amd64

// simd_asm.go - used to check what assembler is generated by SIMD function calls

package main

import (
	"math"
	"simd/archsimd"
)

// $ go version   # go1.26
// $ cd main
// $ GOEXPERIMENT=simd go build simd_asm.go
// $ objdump -d simd_asm.exe > s.asm

// Notes
// %rip = instruction pointer
// %rsp = stack pointer
// %rcx = CX register
// XMM0 - XMM7 = 128bit (16 byte) registers - AVX?
// YMM0 - YMM15 = 256bit (32 byte) registers - AVX2

