func main() {
	v := archsimd.LoadInt64x4(&[4]int64{math.MaxInt64, 0, -1, math.MinInt64})
	r := v.Equal(v) // VPCMPEQQ
	// 140079f0d:	c4 e2 7d 29 c8       	vpcmpeqq %ymm0,%ymm0,%ymm1

	vTrue := r.ToInt64x4()
	vNot := v.Xor(vTrue) // VPXOR
	// c5 fd ef c1          	vpxor  %ymm1,%ymm0,%ymm0

	println(vNot.String())
}
